function sqlplusIdentifier(value){return value.startsWith('"')?value.slice(1,-1).replace(/""/g,'"'):value.toUpperCase()}
const sqlPlus={settings:{SERVEROUTPUT:'ON',DEFINE:'&',HEADING:'ON',FEEDBACK:'ON',VERIFY:'OFF',ECHO:'OFF',TIMING:'OFF',AUTOCOMMIT:'OFF',PAGESIZE:'14',LINESIZE:'80',NULL:'',SQLPROMPT:'SQL>'},defines:{},columns:{},spoolFile:'',spoolLines:[],transcript:[],lastBuffer:'',whenever:'',exited:false,scriptDepth:0,commandHistory:JSON.parse(localStorage.getItem('ora-sqlplus-command-history')||'[]'),historyIndex:0,historyDraft:''};function restoreSqlPlusTranscript(){let records;try{records=JSON.parse(localStorage.getItem('ora-sqlplus-transcript')||'[]')}catch{records=[]}if(!Array.isArray(records)||!records.length)return;sqlPlus.transcript=records.filter(record=>record&&((record.type==='command'&&typeof record.text==='string')||(record.type==='line'&&typeof record.text==='string'))).slice(-2500);if(!sqlPlus.transcript.length)return;const output=document.querySelector('#cliOutput');output.replaceChildren();sqlPlus.restoringTranscript=true;let previousCommand=null;for(const record of sqlPlus.transcript){if(record.type==='command'){if(previousCommand)groupCliExchange(previousCommand);previousCommand=appendCliCommand(record.text,record.prompt||sqlPlus.settings.SQLPROMPT);if(record.status==='error')previousCommand.classList.add('cli-command-error');else if(record.status==='success')previousCommand.classList.add('cli-command-success')}else appendCli(record.text,record.kind||'cli-output-line')}if(previousCommand)groupCliExchange(previousCommand);sqlPlus.restoringTranscript=false;createCliPrompt()}restoreSqlPlusTranscript();
