async function shareCliCode(){const text=sqlPlus.commandHistory.join('\r\n');if(!text){resultMeta.textContent='No SQL*Plus commands to share';return}try{if(navigator.share)await navigator.share({title:'SQL*Plus session',text});else{await navigator.clipboard.writeText(text);resultMeta.textContent='SQL*Plus history copied to clipboard'}}catch(error){if(error.name!=='AbortError'){try{await navigator.clipboard.writeText(text);resultMeta.textContent='SQL*Plus history copied to clipboard'}catch{resultMeta.textContent='Clipboard unavailable'}}}}
function expandSqlPlusVariables(sql){if(sqlPlus.settings.DEFINE==='OFF')return sql;return sql.replace(/&&?([A-Za-z][A-Za-z0-9_$#]*)/g,(whole,key)=>{if(Object.hasOwn(sqlPlus.defines,key))return sqlPlus.defines[key];const value=window.prompt(`Enter value for ${key}:`);if(value===null)return whole;sqlPlus.defines[key]=value;return value})}
