function activeSqlInput(){return document.querySelector('#cliView').hidden?editor:document.querySelector('#cliInput')}
function updateFindCount(){const target=findReplaceTarget(),query=findInput.value;if(!target||!query){findCount.textContent='';return}const haystack=findCaseSensitive?target.value:target.value.toLowerCase(),needle=findCaseSensitive?query:query.toLowerCase();let count=0,index=0;while((index=haystack.indexOf(needle,index))!==-1){count++;index+=Math.max(1,needle.length)}findCount.textContent=count?`0/${count}`:'0/0'}
let findReplaceTarget=activeSqlInput;
