function findMatch(direction=1,focusTarget=false){const target=findReplaceTarget(),query=findInput.value;if(!target||!query)return;const text=findCaseSensitive?target.value:target.value.toLowerCase(),needle=findCaseSensitive?query:query.toLowerCase();let index=direction>0?text.indexOf(needle,target.selectionEnd):text.lastIndexOf(needle,Math.max(0,target.selectionStart-1));if(index<0)index=direction>0?text.indexOf(needle):text.lastIndexOf(needle);if(index>=0){if(focusTarget)target.focus({preventScroll:true});target.setSelectionRange(index,index+query.length);const highlight=target.id==='cliInput'?target.parentElement.querySelector('.cli-input-highlight'):document.querySelector('#editorHighlight');if(highlight)renderSqlHighlight(target,highlight,target.id==='editor'?'editor':'cli')}updateFindCount()}
function replaceFindMatch(){const target=findReplaceTarget(),query=findInput.value;if(!target||!query)return;if(target.value.slice(target.selectionStart,target.selectionEnd).toLowerCase()!==query.toLowerCase())findMatch(1);if(target.value.slice(target.selectionStart,target.selectionEnd).toLowerCase()===query.toLowerCase()){const start=target.selectionStart;target.setRangeText(replaceInput.value,start,target.selectionEnd,'end');target.dispatchEvent(new Event('input',{bubbles:true}));findMatch(1,true)}updateFindCount()}
function replaceAllFindMatches(){const target=findReplaceTarget(),query=findInput.value;if(!target||!query)return;const escaped=query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),expression=new RegExp(escaped,findCaseSensitive?'g':'gi'),before=target.value,caret=target.selectionStart;target.value=before.replace(expression,replaceInput.value);target.setSelectionRange(Math.min(caret,target.value.length),Math.min(caret,target.value.length));target.dispatchEvent(new Event('input',{bubbles:true}));target.focus({preventScroll:true});updateFindCount()}
function normalizeSpecialWhitespace(){const target=findReplaceTarget();if(!target)return;const before=target.value,caret=target.selectionStart,normalize=value=>value.replace(/[\u00a0\u1680\u2000-\u2006\u2008-\u200a\u202f\u205f\u3000]/g,' ').replace(/[\u200b\u200c\u200d\u2060\ufeff]/g,'');target.value=normalize(before);const nextCaret=normalize(before.slice(0,caret)).length;target.setSelectionRange(nextCaret,nextCaret);target.dispatchEvent(new Event('input',{bubbles:true}));target.focus({preventScroll:true});updateFindCount()}
findInput.addEventListener('input',updateFindCount);document.querySelector('#findCaseToggle').addEventListener('click',event=>{findCaseSensitive=!findCaseSensitive;event.currentTarget.classList.toggle('active',findCaseSensitive);updateFindCount()});document.querySelector('#findPrev').addEventListener('click',()=>findMatch(-1,true));document.querySelector('#findNext').addEventListener('click',()=>findMatch(1,true));document.querySelector('#replaceCurrent').addEventListener('click',replaceFindMatch);document.querySelector('#replaceAll').addEventListener('click',replaceAllFindMatches);document.querySelector('#normalizeSpecialWhitespace').addEventListener('click',normalizeSpecialWhitespace);document.querySelector('#closeFindReplace').addEventListener('click',()=>{if(findPanel.open)findPanel.close();activeSqlInput().focus({preventScroll:true})});
const supportedShortcuts=[['Ctrl+K','Open find and replace'],['Ctrl+F','Find in active editor'],['Ctrl+H','Replace in active editor'],['Enter','SQL*Plus: execute complete command; otherwise add a line'],['Shift+Enter','SQL*Plus: add a new line'],['↑ / ↓','SQL*Plus: browse command history'],['Ctrl+L','SQL*Plus: clear screen'],['Ctrl+Enter','Online compiler: run selected statement(s)'],['Ctrl+Shift+Enter','Online compiler: run script'],['Ctrl+S','Save current SQL file'],['Ctrl+Z / Ctrl+Y','Undo / redo'],['Tab','Indent by two spaces'],['Ctrl+[ / Ctrl+]','Outdent / indent current line'],['Ctrl+/','Toggle line comment'],['Alt+Shift+A','Toggle block comment'],['Alt+↑ / Alt+↓','Move line up / down'],['Ctrl+Shift+K','Delete current line'],['Ctrl+C / Ctrl+X','Copy / cut current line when no text is selected'],['Ctrl++ / Ctrl+-','Increase / decrease editor font'],['F11','Toggle full screen'],['Alt+Z','Toggle word wrap'],['( [ { \' "','Insert paired brackets or quotes']];document.querySelector('#shortcutList').innerHTML=supportedShortcuts.map(([key,description])=>`<div class="shortcut-row"><kbd>${esc(key)}</kbd><span>${esc(description)}</span></div>`).join('');function addShortcutButton(container){if(!container||container.querySelector('[data-shortcut-help]'))return;const button=document.createElement('button');button.type='button';button.className='plain-button';button.dataset.shortcutHelp='true';button.textContent='⌨ Shortcuts';button.title='View supported keyboard shortcuts';button.addEventListener('click',()=>document.querySelector('#shortcutDialog').showModal());container.append(button)}addShortcutButton(document.querySelector('.editor-tools'));addShortcutButton(document.querySelector('.cli-tools'));document.querySelector('#closeShortcuts').addEventListener('click',()=>document.querySelector('#shortcutDialog').close());
document.addEventListener('keydown',event=>{const mod=event.ctrlKey||event.metaKey;if(mod&&event.key.toLowerCase()==='k'&&(event.target===editor||event.target?.id==='cliInput')){event.preventDefault();openFindReplace('replace');return}if(mod&&event.target?.id==='cliInput'&&event.key.toLowerCase()==='f'){event.preventDefault();openFindReplace('find');return}if(mod&&event.target?.id==='cliInput'&&event.key.toLowerCase()==='h'){event.preventDefault();openFindReplace('replace');replaceInput.focus();return}if(event.key==='Escape'&&findPanel.open){if(findPanel.open)findPanel.close();activeSqlInput().focus({preventScroll:true});return}});
function extractFirstCliStatement(source){const firstStatementStart=source.search(/\S/);if(firstStatementStart<0)return null;const beginning=source.slice(firstStatementStart).toUpperCase();if(/^(?:DECLARE|BEGIN)\b/.test(beginning)||/^CREATE\s+(?:OR\s+REPLACE\s+)?(?:EDITIONABLE\s+)?(?:PROCEDURE|FUNCTION|PACKAGE|TRIGGER|TYPE)\b/.test(beginning))return null;let single=false,double=false,lineComment=false,blockComment=false;for(let i=0;i<source.length;i++){const ch=source[i],next=source[i+1];if(lineComment){if(ch==='\n')lineComment=false;continue}if(blockComment){if(ch==='*'&&next==='/'){blockComment=false;i++}continue}if(single){if(ch==="'"&&next==="'"){i++;continue}if(ch==="'")single=false;continue}if(double){if(ch==='"'&&next==='"'){i++;continue}if(ch==='"')double=false;continue}if(ch==='-'&&next==='-'){lineComment=true;i++;continue}if(ch==='/'&&next==='*'){blockComment=true;i++;continue}if(ch==="'"){single=true;continue}if(ch==='"'){double=true;continue}if(ch===';'){const remainder=source.slice(i+1);if(/^[ \t]*\r?\n/.test(remainder)&&remainder.replace(/^[ \t]*\r?\n/,'').trim())return{statement:source.slice(0,i+1).trim(),remainder:remainder.replace(/^[ \t]*\r?\n/,'')}}}return null}function oracleSqlFeedback(sql,data={}){if(data.columns?.length)return data.message||'Query completed';const source=String(sql||'').replace(/^\s*(?:(?:--[^\r\n]*|\/\*[\s\S]*?\*\/)\s*)*/,'').trim().replace(/;\s*$/,'');const identifier='(?:"(?:""|[^"])*"|[A-Za-z][A-Za-z0-9_$#]*)';const objectMatch=source.match(new RegExp('^(CREATE(?:\\s+OR\\s+REPLACE)?|DROP|ALTER|TRUNCATE)\\s+(?:EDITIONABLE\\s+)?(TABLE|VIEW|MATERIALIZED\\s+VIEW|INDEX|SEQUENCE|SYNONYM|PROCEDURE|FUNCTION|PACKAGE|TRIGGER|TYPE)\\s+('+identifier+'(?:\\s*\\.\\s*'+identifier+')?)','i'));if(objectMatch){const action=objectMatch[1].toUpperCase().startsWith('CREATE')?'created':objectMatch[1].toUpperCase(),type=objectMatch[2].replace(/\s+/g,' ').toUpperCase(),rawName=objectMatch[3].split('.').at(-1).trim(),name=rawName.startsWith('"')?rawName.slice(1,-1).replace(/""/g,'"'):rawName.toUpperCase(),label=type==='MATERIALIZED VIEW'?'Materialized view':type[0]+type.slice(1).toLowerCase();if(action==='created')return `${label} ${name} created.`;if(action==='DROP')return `${label} ${name} dropped.`;if(action==='ALTER')return `${label} ${name} altered.`;if(action==='TRUNCATE')return `${label} ${name} truncated.`}const upper=source.toUpperCase(),affected=Number(data.rowsAffected);if(/^INSERT\b/.test(upper))return Number.isFinite(affected)?`${affected} row${affected===1?'':'s'} created.`:'1 row created.';if(/^UPDATE\b/.test(upper))return Number.isFinite(affected)?`${affected} row${affected===1?'':'s'} updated.`:'Statement executed.';if(/^DELETE\b/.test(upper))return Number.isFinite(affected)?`${affected} row${affected===1?'':'s'} deleted.`:'Statement executed.';if(/^MERGE\b/.test(upper))return Number.isFinite(affected)?`${affected} row${affected===1?'':'s'} merged.`:'Statement executed.';if(/^COMMIT\b/.test(upper))return 'Commit complete.';if(/^ROLLBACK\b/.test(upper))return 'Rollback complete.';return data.message||'Statement executed.'}